/* Full-height app frame: the table container scrolls, not the document. */
.app-content {
    box-sizing: border-box;
    height: 100vh;
    min-height: 480px;
    padding: var(--g-spacing-6) var(--g-spacing-8);
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.app-content__page {
    flex: 1;
    min-height: 0;
    min-width: 0;
}

.app-content__page > :first-child {
    flex-shrink: 0;
}

.orders {
    flex: 1;
    min-height: 0;
    min-width: 0;

    /* @gravity-ui/table CSS API: theme-aware drag preview instead of the hard-coded light defaults. */
    --gt-table-drag-overlay-background: var(--g-color-base-float);
    --gt-table-drag-overlay-shadow: 0 3px 12px var(--g-color-sfx-shadow);
    --gt-table-drag-overlay-border-radius: var(--g-border-radius-m);
    --gt-table-reordering-insertion-line-color: var(--g-color-line-brand);
}

.orders__toolbar {
    flex-shrink: 0;
}

.orders__search {
    flex: 1 1 280px;
    min-width: 0;
    max-width: 420px;
}

.orders__search-icon {
    margin-inline-start: var(--g-spacing-2);
    color: var(--g-color-text-secondary);
}

.orders__selection {
    flex-shrink: 0;
    margin-inline-start: auto;
}

/* Horizontal and vertical scroll live inside the table widget only. */
.orders__table-container {
    flex: 1;
    min-height: 0;
    overflow: auto;
    border: 1px solid var(--g-color-line-generic);
    border-radius: var(--g-border-radius-l);
    background: var(--g-color-base-background);
}

.orders-table {
    min-width: 100%;
}

.orders-table__row {
    cursor: pointer;
}

.orders-table__row:hover {
    background: var(--g-color-base-simple-hover);
}

.orders-table__row_selected,
.orders-table__row_selected:hover {
    background: var(--g-color-base-selection);
}

.orders-table__group {
    background: var(--g-color-base-generic);
    margin: calc(-1 * var(--g-spacing-2));
    padding: var(--g-spacing-1) var(--g-spacing-2);
}

.orders__empty {
    padding: var(--g-spacing-8) 0;
}

